corrected_code:
@Controller('devices')
@UseGuards(JwtAuthGuard)
export class DeviceController {
  constructor(private readonly deviceService: DeviceManagementService) {}

  @Post(':deviceId/reboot')
  async triggerReboot(@Param('deviceId') deviceId: string, @Req() req: AuthenticatedRequest) {
    const device = await this.deviceService.findUserDevice(deviceId, req.user.id);
    if (!device) throw new ForbiddenException('Access denied to target device');
    await this.deviceService.sendMqttCommand(device.hardwareSerial, 'REBOOT');
    return { status: 'reboot_dispatched', deviceId };
  }
}
